'use client'

export function Entry() {
	const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
		if ((e.ctrlKey || e.metaKey) && (e.key === 'Enter' || e.key === 'NumpadEnter')) {
			e.preventDefault()
			e.currentTarget.form?.requestSubmit()
		}
	}

	return (
		<div>
			<textarea
				name="entry"
				rows={20}
				required
				onKeyDown={handleKeyDown}
			/>
		</div>
	)
}

